<a class="btn btn-outline-secondary mb-3" href="<?= BASE_URL ?>/visits">Volver a agenda</a><h1 class="h3 mb-4"><?= e($title) ?></h1>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?>
<?php if ($errors): ?><div class="alert alert-danger" role="alert"><ul class="mb-0"><?php foreach ($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="card card-body mb-3"><p class="mb-1"><strong>Cliente:</strong> <?= e($visit['cliente']) ?></p><p class="mb-0"><strong>Inmueble:</strong> <?= e($visit['titulo'] ?? 'Sin inmueble') ?></p></div>
<form class="card card-body" method="post" action="<?= BASE_URL ?>/visits/save?<?= isset($visit['id']) ? 'id='.(int)$visit['id'] : 'lead_id='.(int)$visit['lead_id'] ?>"><?= Csrf::field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label" for="fecha_hora">Fecha y hora (Lima) *</label><input class="form-control" id="fecha_hora" name="fecha_hora" type="datetime-local" required value="<?= e(isset($visit['fecha_hora']) ? str_replace(' ','T',substr($visit['fecha_hora'],0,16)) : '') ?>"></div>
<div class="col-md-6"><label class="form-label" for="vendedor_id">Vendedor *</label><select class="form-select" id="vendedor_id" name="vendedor_id" required <?= $user['rol']==='vendedor' ? 'disabled' : '' ?>><option value="">Seleccionar</option><?php foreach ($sellers as $seller): ?><option value="<?= (int)$seller['id'] ?>" <?= (int)($visit['vendedor_id'] ?? 0)===(int)$seller['id'] ? 'selected' : '' ?>><?= e($seller['nombre']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="modalidad">Modalidad</label><select class="form-select" id="modalidad" name="modalidad"><?php foreach (Visit::MODES as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($visit['modalidad'] ?? '')===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="estado_visita">Estado</label><select class="form-select" id="estado_visita" name="estado_visita"><?php foreach (Visit::STATES as $value=>$label): if (!isset($visit['id']) && !in_array($value,['solicitada','confirmada'],true)) continue; ?><option value="<?= e($value) ?>" <?= ($visit['estado_visita'] ?? '')===$value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div>
<div class="col-12"><label class="form-label" for="resultado">Observaciones / resultado</label><textarea class="form-control" id="resultado" name="resultado" maxlength="4000" rows="4"><?= e($visit['resultado'] ?? '') ?></textarea><p class="small text-muted mt-2">El resultado es obligatorio al marcar una visita realizada. No se envían notificaciones automáticas. Se bloquean citas del mismo vendedor a la misma hora; no se calculan duraciones.</p></div><div class="col-12"><button class="btn btn-primary">Guardar visita</button></div></div></form>
